import sys

def main():
    data = sys.stdin.read().strip().split()
    if not data:
        return
    n = int(data[0])
    idx = 1
    matrix = {}
    out_lines = []
    for _ in range(n):
        op = data[idx]; idx += 1
        if op == 'INSERT':
            row = int(data[idx]); col = int(data[idx+1]); val = int(data[idx+2]); idx += 3
            if val != 0:
                matrix[(row, col)] = val
            else:
                # if inserting 0, remove if exists
                matrix.pop((row, col), None)
        elif op == 'DELETE':
            row = int(data[idx]); col = int(data[idx+1]); idx += 2
            matrix.pop((row, col), None)
        elif op == 'RETRIEVE':
            row = int(data[idx]); col = int(data[idx+1]); idx += 2
            out_lines.append(str(matrix.get((row, col), 0)))
    sys.stdout.write('\n'.join(out_lines))

if __name__ == '__main__':
    main()
